"""Align the review package with its authorized simulation/emulation scope."""
from pathlib import Path
from docx import Document
import json,hashlib,csv
R=Path(__file__).resolve().parents[1];P=R/'publication/array'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
d=Document(P/'Array_Manuscript.docx');review=json.loads((P/'virtual_scope_visual_review.json').read_text());audit=json.loads((P/'remediation_manuscript_audit.json').read_text())
assert review['status']=='passed_page_by_page_review' and review['docx_sha256']==sha(P/'Array_Manuscript.docx') and review['pdf_sha256']==sha(P/'Array_Manuscript.pdf') and audit['final_docx_sha256']==review['docx_sha256']
mcu=json.loads((R/'outputs/mcu_deadline_v2/analysis.json').read_text());misses=sum(x['signed_deadline_misses'] for x in mcu['rows']);assert misses==68
radio=json.loads((R/'outputs/cooja_radio_energy_v1/analysis.json').read_text());assert radio['runs']==600 and not radio['physical_current_measured']
matched=json.loads((R/'outputs/remediation_v1/analysis.json').read_text());assert matched['runs']==1440 and matched['status']=='completed_block_factorial_analysis'
abstract=next(d.paragraphs[i+1].text for i,p in enumerate(d.paragraphs) if p.text=='Abstract')
summary=f"The paper is a simulation/emulation benchmark with {review['pages']} reviewed pages, a {len(abstract.split())}-word abstract, 16 figures, 13 tables, 25 references and 10 native equations. It combines controlled feedback comparisons, frozen-policy transfer diagnostics, compiled-MCU emulation and explicit negative deadline outcomes. No new experiments or altered acceptance criteria accompany this scope clarification."
limits='Physical RF/current acquisition and production-board security are outside the selected research scope and have not been validated. They are not completed hardware gates. The original signed endpoint still misses 68/200 deadlines in each O3/LTO diagnostic; deadlines and endpoint remain unchanged. These failures are retained results, not a passed real-time compliance claim. Native Cooja radio states and assumed current ratios are not physical energy measurements.'
authors='Equal contribution, no funding and no competing interests are supplied by the corresponding author. Publication permissions are recorded as corresponding-author-reported. Exact-version independent coauthor confirmation and exclusivity/overlap declarations are not inferred.'
submission='This package is ready for author review within its declared virtual scope. Array-specific authenticated portal checks, required final declarations and the portal-generated review PDF remain unchecked; no submission or message has been sent. The official guide previously returned 403. This is not a submission or acceptance certificate.'
report=dict(status='review_package_consistent_with_declared_virtual_scope',scope_authorized_at='2026-10-19T07:24:15+05:30',artifact_checks_passed=True,scope='Simulation/emulation benchmark',original_signed_deadline_gate_passed=False,signed_deadline_misses=68,deadline_ms=[90,350,1500],acceptance_criteria_changed=False,new_experiments_executed=0,physical_validation_completed=False,production_security_validated=False,outside_declared_scope=['Physical RF/current measurement','Production-board security certification'],remaining_submission_actions=['Authenticated Array requirements and portal PDF','Exclusivity and overlap confirmation','Exact-version final author review'],manuscript_docx_sha256=review['docx_sha256'],manuscript_pdf_sha256=review['pdf_sha256'],interpretation='Consistency of the review artifacts does not certify physical validation, real-time compliance, journal acceptance or submission.')
(P/'VIRTUAL_SCOPE_COMPLETION_REPORT.json').write_text(json.dumps(report,indent=2)+'\n')
(P/'FINAL_COMPLETION_REPORT.json').write_text(json.dumps(report,indent=2)+'\n')
checks=json.loads((P/'document_checks.json').read_text());checks.update(pages=review['pages'],rendered_pages=review['pages'],abstract_words=len(abstract.split()),docx_sha256=review['docx_sha256'],pdf_sha256=review['pdf_sha256'],selected_scope='simulation/emulation benchmark',scope_artifact_checks_passed=True,physical_validation=False,production_mcu_security_validated=False,original_signed_deadline_compliance=False,full_validation_complete=False,scope_only_prose_change_after_regression=True,full_suite_rerun_this_revision=False,implementation_unchanged_since_passed_145_test_regression=True)
(P/'document_checks.json').write_text(json.dumps(checks,indent=2)+'\n')
(P/'README.md').write_text('# Simulation and emulation manuscript package\n\n'+summary+'\n\n'+limits+'\n\n'+authors+'\n\n'+submission+'\n\nDownload `Array_Manuscript.docx`, `Array_Manuscript.pdf` and `Array_Figures_PNG_PDF_SVG.zip` (48 exports). The unchanged implementation passed 145 regression tests and four mutation subchecks at c9977c9cd8c44791d7abc727208e4b63c8362500; the current change is scope prose only. Reproduce with `scripts/apply_virtual_scope.py`, both manuscript audits, the document renderer, actual visual review and `scripts/finalize_virtual_scope.py`. See `VIRTUAL_SCOPE_COMPLETION_REPORT.json` and `virtual_scope_preservation_audit.json`.\n')
for name in ['SUBMISSION_STATUS.md','ARRAY_TARGET_AND_VIRTUAL_STATUS.md','PENDING_VALIDATION_REGISTER.md']:
 (R/'docs'/name).write_text('# Current virtual benchmark scope\n\n'+summary+'\n\n'+limits+'\n\n'+authors+'\n\n'+submission+'\n\nEarlier records retain the original broader physical-validation request. They must not be read as completed hardware evidence or as mandatory hardware work within this selected paper scope.\n')
p=R/'README.md';s=p.read_text();i=s.index('> Historical transport stage:');p.write_text('## Current simulation and emulation benchmark\n\n'+summary+'\n\n'+limits+'\n\n'+submission+'\n\nSee [the manuscript package](publication/array/README.md).\n\n'+s[i:])
p=R/'docs/REMEDIATION_COMPLETION_REPORT.md';s=p.read_text();p.write_text('# Current selected scope\n\n'+summary+'\n\n'+limits+'\n\n'+authors+'\n\n'+submission+'\n\n---\n\n'+s)
p=R/'docs/ARRAY_SUBMISSION_CHECKLIST.md';s=p.read_text();p.write_text('# Current selected scope and submission boundary\n\n'+summary+'\n\n'+limits+'\n\n'+authors+'\n\n'+submission+'\n\n---\n\n## Earlier preparation record\n\n'+s)
p=R/'docs/REMEDIATION_REPRODUCTION.md';p.write_text(p.read_text()+'\n## Selected virtual-scope revision\n\nRun `python scripts/apply_virtual_scope.py` from the retained 5d199b3 source baseline specified by the script. Run both manuscript audits, render and inspect the Word/PDF, then run `python scripts/finalize_virtual_scope.py` with the current reviewed hashes. No simulations, timing criteria or historical statistical families are changed. The original full-hardware gate remains distinct and incomplete; `VIRTUAL_SCOPE_COMPLETION_REPORT.json` checks artifact consistency only.\n')
p=P/'Cover_letter_DRAFT.txt';s=p.read_text();s=s.replace('The paper examines whether','The submitted research scope is simulation and compiled-MCU emulation. Physical RF/current measurements and production security certification are not claimed. The paper examines whether');s=s.replace('Physical RF/current, protected device keys and reset-safe production state remain unvalidated.','Physical RF/current, protected device keys and reset-safe production state remain unevaluated outside this declared virtual scope.');p.write_text(s)
p=R/'docs/REMEDIATION_CONCERN_MATRIX.csv'
with p.open(newline='') as f:r=csv.DictReader(f);fields=r.fieldnames;rows=list(r)
for row in rows:
 for key,val in row.items():
  if val and val in ['H: physical RF and energy','H: production security']:
   row[fields[1]]='SCIENTIFIC LIMITATION';row[fields[-1]]='Outside the authorized simulation/emulation paper scope; no physical or production-security validation claimed. A future deployment claim requires actual board evidence.'
with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print(json.dumps(report,indent=2))
